import { expect, test, uniqueName } from "../../fixtures";

function utcDatePlus(days: number): string {
  return new Date(Date.now() + days * 86_400_000).toISOString().slice(0, 10);
}

const examples: { days: number; include: boolean }[] = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

test.describe("Insurance expiring within 30 days is flagged", () => {
  for (const { days, include } of examples) {
    test(`insurance expiring in ${days} days ${include ? "includes" : "does not include"} insurance_expiring_soon`, { tag: "@REV-08" }, async ({ apiAs }) => {
      const member = await apiAs("member");

      // Given a vendor whose insurance certificate expires in <days> days
      const createRes = await member.post("/api/vendors", {
        data: { name: uniqueName(`REV08 ${days}d`), category: "services", contact_email: "ops@example.com" },
      });
      expect(createRes.status(), await createRes.text()).toBe(201);
      const vendor = await createRes.json();

      const expiry = utcDatePlus(days);
      const content = `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
      const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: { name: "insurance_certificate.txt", mimeType: "text/plain", buffer: Buffer.from(content, "utf-8") },
        },
      });
      expect(uploadRes.status(), await uploadRes.text()).toBe(201);
      const doc = await uploadRes.json();

      await expect
        .poll(async () => {
          const r = await member.get(`/api/documents/${doc.id}`);
          return r.status() === 200 ? (await r.json()).status : `http ${r.status()}`;
        }, { timeout: 30_000, message: "document should finish extraction" })
        .toBe("extracted");

      const extRes = await member.get(`/api/documents/${doc.id}/extraction`);
      expect(extRes.status(), await extRes.text()).toBe(200);
      expect((await extRes.json()).fields.expiry_date.value).toBe(expiry);

      // When I request the vendor
      const vendorRes = await member.get(`/api/vendors/${vendor.id}`);
      const body = await vendorRes.text();
      expect(vendorRes.status(), body).toBe(200);
      const flags: string[] = JSON.parse(body).flags;

      // Then the vendor flags <include> "insurance_expiring_soon"
      if (include) {
        expect(flags, body).toContain("insurance_expiring_soon");
      } else {
        expect(flags, body).not.toContain("insurance_expiring_soon");
      }
    });
  }
});
